+  const upper = values.map(value => Math.min(1, value + halfUnit));
+  const remaining = 1 - lower.reduce((sum, value) => sum + value, 0);
+  if (remaining < -epsilon || upper.reduce((sum, value) => sum + value, 0) < 1 - epsilon) invalidDecisionResponse();
